#!/system/bin/sh
# chroot container entry, generated by ChrootRuntime. Runs as root via su.
# Tears itself down: kills every process whose root is the guest rootfs and
# lazily unmounts every bind, then sweeps /proc/mounts for strays -- so a
# stopped or killed app does not leave mounts or procs for the next launch.
set -u

ROOT='__ROOT__'
APP_PID=__APP_PID__
BINDS_FILE='__BINDS_FILE__'
BINDS_REV_FILE='__BINDS_REV_FILE__'
PIGGYBACK=__PIGGYBACK__
CLEANED=0

mount_binds() {
    [ -f "$BINDS_FILE" ] || return 0
    while IFS= read -r spec; do
        [ -n "$spec" ] || continue
        host=${spec%%:*}
        guest=${spec#*:}
        [ "$host" = "$spec" ] && guest=$host
        target="$ROOT$guest"
        if [ -d "$host" ]; then
            mkdir -p "$target"
        else
            mkdir -p "$(dirname "$target")"
            [ -e "$target" ] || : > "$target"
        fi
        mount --bind "$host" "$target" 2>/dev/null || echo "chroot: bind $host -> $target failed" >&2
    done < "$BINDS_FILE"
}

kill_in_root() {
    for p in /proc/[0-9]*; do
        pid=${p#/proc/}
        [ "$pid" = "$$" ] && continue
        r=$(readlink "$p/root" 2>/dev/null) || continue
        [ "$r" = "$ROOT" ] || continue
        kill -9 "$pid" 2>/dev/null || true
    done
}

cleanup_mounts() {
    if [ -f "$BINDS_REV_FILE" ]; then
        while IFS= read -r spec; do
            [ -n "$spec" ] || continue
            guest=${spec#*:}
            umount -l "$ROOT$guest" 2>/dev/null || true
        done < "$BINDS_REV_FILE"
    fi
    # Final sweep: anything still mounted under the rootfs, deepest first.
    awk -v r="$ROOT" '$2==r || index($2,r"/")==1 {print $2}' /proc/mounts 2>/dev/null | sort -r | while read -r m; do
        umount -l "$m" 2>/dev/null || true
    done
}

cleanup() {
    [ "$CLEANED" = 1 ] && return 0
    CLEANED=1
    trap '' EXIT INT TERM HUP
    # A piggyback terminal rides an already-running session's mounts and must not
    # tear them down on exit -- killing rootfs processes or unmounting here would
    # take the whole Steam/gamescope session down with the terminal.
    if [ "$PIGGYBACK" = 1 ]; then
        rm -f "$BINDS_FILE" "$BINDS_REV_FILE"
        return 0
    fi
    kill_in_root
    cleanup_mounts
    rm -f "$BINDS_FILE" "$BINDS_REV_FILE"
}
trap cleanup EXIT INT TERM HUP

WATCHDOG=
if [ "$PIGGYBACK" != 1 ]; then
    # If the app dies, no one will signal us; the watchdog cleans up and leaves.
    ( while kill -0 "$APP_PID" 2>/dev/null; do sleep 5; done; cleanup ) &
    WATCHDOG=$!
fi

mount_binds
setsid chroot "$ROOT" __GUEST__
RC=$?
[ -n "$WATCHDOG" ] && kill "$WATCHDOG" 2>/dev/null || true
cleanup
exit "$RC"
